"approved","is_test":false,"updated_at":"2026-09-16T09:45:45.612023+00:00"},{"id":"fa4c50b6-13b7-4509-bf17-f35165738a50","status":"in_progress","is_test":false,"updated_at":"2026-08-27T17:42:10.368686+00:00"},{"id":"fb49d2f4-edf1-4f5f-bb20-f07f9a2773b1","status":"in_progress","is_test":false,"updated_at":"2026-09-13T20:21:53.662676+00:00"}],"gps_digest":"1e02617590f43a301dea6de712b05ad2","gps_points":2348,"captured_at":"2026-10-25T11:12:49.90011+00:00","excluded_info":[{"id":"9dc3e5fd-21bf-4293-a322-3a516546cfed","status":"pending_review","is_test":false,"updated_at":"2026-09-12T19:41:53.24+00:00"}]}'::jsonb);
do $cleanup$
declare snapshot jsonb; c jsonb; s jsonb; excluded jsonb; digest text; n integer;
begin
 select payload into snapshot from gps_cleanup_snapshot;
 perform pg_advisory_xact_lock(hashtext('gps-test-cleanup-20261025'));
 if jsonb_array_length(snapshot->'campaigns')<>103 or jsonb_array_length(snapshot->'sessions')<>22 then
  raise exception 'Scope changed'; end if;
 select md5(string_agg(concat_ws('|',id,campaign_id,session_id,driver_id,lat,lng,accuracy,speed,heading,recorded_at,created_at),E'\n' order by id))
 into digest from public.gps_tracking_points;
 if digest is distinct from snapshot->>'gps_digest' then raise exception 'GPS changed since snapshot'; end if;
 for c in select value from jsonb_array_elements(snapshot->'campaigns') loop
  perform 1 from public.campaigns where id=(c->>'id')::uuid and is_test=(c->>'is_test')::boolean
   and status=c->>'status' and updated_at is not distinct from (c->>'updated_at')::timestamptz for update;
  if not found then raise exception 'Campaign changed: %',c->>'id'; end if;
 end loop;
 for s in select value from jsonb_array_elements(snapshot->'sessions') loop
  perform 1 from public.delivery_sessions where id=(s->>'id')::uuid and status='started'
   and updated_at is not distinct from (s->>'updated_at')::timestamptz for update;
  if not found then raise exception 'Session changed: %',s->>'id'; end if;
 end loop;
 -- Reuse canonical Admin session cancellation, including its existing audit.
 perform set_config('request.jwt.claim.sub',(select id::text from auth.users where lower(email)='fenice.sp@gmail.com' limit 1),true);
 perform set_config('request.jwt.claim.email','fenice.sp@gmail.com',true);
 perform set_config('request.jwt.claim.role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',(select id from auth.users where lower(email)='fenice.sp@gmail.com' limit 1),'email','fenice.sp@gmail.com','role','authenticated')::text,true);
 for s in select value from jsonb_array_elements(snapshot->'sessions') loop
  perform public.gps_transition_session_v3((s->>'id')::uuid,'cancel',null,null);
  update public.delivery_sessions set metadata=coalesce(metadata,'{}')||jsonb_build_object('cleanup_run_id',snapshot->>'run_id')
   where id=(s->>'id')::uuid;
 end loop;
 update public.campaigns c set is_test=true,status=case when c.status='in_progress' then 'archived' else c.status end
 where c.id in (select (value->>'id')::uuid from jsonb_array_elements(snapshot->'campaigns'));
 get diagnostics n = row_count;
 if n<>103 then raise exception 'Unexpected campaign update count %',n; end if;
 select md5(string_agg(concat_ws('|',id,campaign_id,session_id,driver_id,lat,lng,accuracy,speed,heading,recorded_at,created_at),E'\n' order by id))
 into digest from public.gps_tracking_points;
 if digest is distinct from snapshot->>'gps_digest' then raise exception 'GPS changed'; end if;
 for excluded in select value from jsonb_array_elements(snapshot->'excluded_info') loop
  perform 1 from public.campaigns where id=(excluded->>'id')::uuid and is_test=(excluded->>'is_test')::boolean
   and status=excluded->>'status' and updated_at is not distinct from (excluded->>'updated_at')::timestamptz;
  if not found then raise exception 'Excluded info campaign changed'; end if;
 end loop;
end;
$cleanup$;
select jsonb_build_object(
 'marked_test',(select count(*) from public.campaigns where id in (select (value->>'id')::uuid from gps_cleanup_snapshot,jsonb_array_elements(payload->'campaigns')) and is_test),
 'archived',(select count(*) from public.campaigns where id in (select (value->>'id')::uuid from gps_cleanup_snapshot,jsonb_array_elements(payload->'campaigns') where value->>'status'='in_progress') and status='archived'),
 'cancelled_sessions',(select count(*) from public.delivery_sessions where metadata->>'cleanup_run_id'='gps-test-cleanup-20261025' and status='cancelled'),
 'remaining_started',(select count(*) from public.delivery_sessions where status='started'),
 'gps_points',(select count(*) from public.gps_tracking_points)) verification;
rollback;
